/** Compute Entrypoint Contract
  *
  * guarantee CASE_18_alarm_mode_priority
  * @param alarm_control_state post-state state variable
  * @param api_monitor_mode incoming data port
  */
pub fn compute_spec_CASE_18_alarm_mode_priority_guarantee(
  alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  (implies!(
    (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::INIT),
    (alarm_control_state == Isolette_Thermostat_Rust::AlarmCommand::Off))) &
    (implies!(
      (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::FAILED),
      (alarm_control_state == Isolette_Thermostat_Rust::AlarmCommand::On)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_19_alarm_numeric_partition
  * @param In_alarm_control_state pre-state state variable
  * @param alarm_control_state post-state state variable
  * @param api_control_basis incoming data port
  * @param api_monitor_mode incoming data port
  */
pub fn compute_spec_CASE_19_alarm_numeric_partition_guarantee(
  In_alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  api_control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode) -> bool
{
  (implies!(
    (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
      api_control_basis.range_available &
      (api_control_basis.current_value_dF < api_control_basis.lower_dF),
    (alarm_control_state == Isolette_Thermostat_Rust::AlarmCommand::On))) &
    (implies!(
      (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF >= api_control_basis.lower_dF) &
        (api_control_basis.current_value_dF < add_alarm_margin(api_control_basis.lower_dF)),
      (alarm_control_state == In_alarm_control_state))) &
    (implies!(
      (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF >= add_alarm_margin(api_control_basis.lower_dF)) &
        (api_control_basis.current_value_dF <= subtract_alarm_margin(api_control_basis.upper_dF)),
      (alarm_control_state == Isolette_Thermostat_Rust::AlarmCommand::Off))) &
    (implies!(
      (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF > subtract_alarm_margin(api_control_basis.upper_dF)) &
        (api_control_basis.current_value_dF <= api_control_basis.upper_dF),
      (alarm_control_state == In_alarm_control_state))) &
    (implies!(
      (api_monitor_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL) &
        api_control_basis.range_available &
        (api_control_basis.current_value_dF > api_control_basis.upper_dF),
      (alarm_control_state == Isolette_Thermostat_Rust::AlarmCommand::On)))
}

