/** CEP-T-Guar: Top-level guarantee contracts for manage_alarm's compute entrypoint
  *
  * @param In_alarm_control_state pre-state state variable
  * @param alarm_control_state post-state state variable
  * @param api_control_basis incoming data port
  * @param api_monitor_mode incoming data port
  * @param api_alarm_control outgoing data port
  */
pub fn compute_CEP_T_Guar(
  In_alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  alarm_control_state: Isolette_Thermostat_Rust::AlarmCommand,
  api_control_basis: Isolette_Thermostat_Rust::MonitorControlBasis,
  api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode,
  api_alarm_control: Isolette_Thermostat_Rust::AlarmCommand) -> bool
{
  let r0: bool = compute_spec_CASE_18_alarm_mode_priority_guarantee(alarm_control_state, api_monitor_mode);
  let r1: bool = compute_spec_CASE_19_alarm_numeric_partition_guarantee(In_alarm_control_state, alarm_control_state, api_control_basis, api_monitor_mode);
  let r2: bool = compute_spec_preserve_alarm_owner_output_guarantee(alarm_control_state, api_alarm_control);

  return r0 && r1 && r2;
}

